// Mirrors src/lib/rarity/engine.ts (model "hybrid-v1"). scripts/check-demo-parity.mjs keeps them in sync.
const MIN_ONE_IN_X = 8, MAX_ONE_IN_X = 2500000;
const MIN_PERCENTILE = 50, MAX_PERCENTILE = 99.97, MIN_TRAIT_RARITY = 2;

function correlationFactor(n) {
  if (n <= 4) return 0.45;
  if (n <= 8) return 0.38;
  if (n <= 14) return 0.30;
  if (n <= 20) return 0.24;
  return 0.20;
}
function rawRarityForAnswer(q, value) {
  if (q.type === "select" && q.options) {
    const opt = q.options.find((o) => o.value === value);
    return opt ? opt.rarity : 50;
  }
  if ((q.type === "number" || q.type === "slider" || q.type === "height") && q.rarityFn) return q.rarityFn(Number(value));
  return 50;
}
function labelForAnswer(q, value) {
  if (q.type === "select" && q.options) {
    const o = q.options.find((o) => o.value === value);
    return o ? o.label : String(value);
  }
  return value + (q.unit ? " " + q.unit : "");
}
function pickArchetype(a, traits) {
  const score = {};
  const add = (k, n) => (score[k] = (score[k] ?? 0) + n);
  const countries = Number(a.countries ?? 0), langs = Number(a.languages ?? 1);
  const income = String(a.income ?? ""), business = String(a.business ?? ""), coding = String(a.coding ?? "");
  const reading = Number(a.reading ?? 0), sleep = String(a.sleep ?? "");
  const intro = Number(a.intro ?? 5), leader = Number(a.leader ?? 5), creative = Number(a.creative ?? 5), risk = Number(a.risk ?? 5);
  const ai = String(a.ai ?? ""), instruments = Number(a.instruments ?? 0), fitness = Number(a.fitness ?? 0);

  add("global_dealmaker", countries * 2 + (income.includes("250") || income === "1m+" ? 25 : 0) + (business !== "no" ? 10 : 0));
  add("silent_strategist", (10 - intro) * 3 + leader * 2 + (reading > 10 ? 10 : 0));
  add("digital_nomad", countries * 3 + (coding !== "no" ? 8 : 0));
  add("chaos_explorer", risk * 4 + (business !== "no" ? 10 : 0));
  add("data_warrior", (coding === "pro" || coding === "expert" ? 25 : coding === "basic" ? 10 : 0) + reading);
  add("visionary_operator", leader * 3 + risk * 2 + (business === "yes" || business === "multi" ? 20 : 0));
  add("modern_renaissance", langs * 5 + instruments * 6 + creative * 2);
  add("curious_thinker", reading + (10 - leader) + creative * 2);
  add("world_connector", intro * 3 + countries + (leader > 6 ? 10 : 0));
  add("maverick_creator", creative * 4 + (business !== "no" ? 8 : 0) + risk * 2);
  add("night_owl_genius", (sleep === "owl" ? 35 : sleep === "late" ? 18 : 0) + creative * 2 + (coding !== "no" ? 5 : 0));
  add("master_builder", fitness * 2 + (ai === "power" ? 6 : 0) + (10 - risk) + leader);

  const byCat = { Travel: "digital_nomad", Career: "global_dealmaker", Skills: "modern_renaissance",
    Personality: "visionary_operator", Technology: "data_warrior", Lifestyle: "night_owl_genius" };
  for (const t of traits) if (t.rarity < 5) add(byCat[t.category] ?? "curious_thinker", 5);

  const winner = Object.entries(score).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "curious_thinker";
  return ARCHETYPES[winner];
}
const CONTINENT_SHARE = { asia: .59, africa: .18, europe: .09, namerica: .075, samerica: .055, oceania: .006, antarctica: .00001 };

function calculateRarity(answers) {
  const traits = [];
  let logSum = 0, answered = 0;
  for (const q of QUESTIONS) {
    if (answers[q.id] === undefined || answers[q.id] === "") continue;
    const raw = rawRarityForAnswer(q, answers[q.id]);
    const r = Math.max(MIN_TRAIT_RARITY, Math.min(99, raw));
    traits.push({ id: q.id, label: q.label, category: q.category, answerLabel: labelForAnswer(q, answers[q.id]), rarity: r });
    logSum += Math.log(r / 100);
    answered++;
  }
  const dampened = logSum * correlationFactor(answered);
  let globalRarity = Math.exp(dampened) * 100;
  globalRarity = Math.max((1 / MAX_ONE_IN_X) * 100, Math.min((1 / MIN_ONE_IN_X) * 100, globalRarity));
  const oneInX = Math.round(Math.max(MIN_ONE_IN_X, Math.min(MAX_ONE_IN_X, 100 / globalRarity)));
  const percentile = Math.max(MIN_PERCENTILE, Math.min(MAX_PERCENTILE, 100 - globalRarity));
  const sorted = [...traits].sort((a, b) => a.rarity - b.rarity);
  const archetype = pickArchetype(answers, traits);
  const confidence = Math.round(Math.min(1, answered / QUESTIONS.length) * 0.85 * 100) / 100;
  return { oneInX, percentile, globalRarity, traits, rarestTraits: sorted.slice(0, 3),
    commonTraits: sorted.slice(-3).reverse(), archetype, confidence, answered };
}
function formatOneInX(n) {
  if (n < 1e6) return n.toLocaleString("en-US");
  if (n < 1e9) return (n / 1e6).toFixed(1) + "M";
  return (n / 1e9).toFixed(2) + "B";
}

